subset_2 <- na.omit(subset_2)

# Reemplazamos los códigos de la variable `disc_fisica` por etiquetas
subset_2$disc_fisica <- factor(
  subset_2$disc_fisica,
  levels = c(1, 2),
  labels = c(
    "No tiene discapacidad",
    "Tiene discapacidad"
  )
)
```
